import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷五·6","description":"易小帖 - 卷五·6","frontmatter":{"title":"卷五·6","description":"易小帖 - 卷五·6"},"headers":[],"relativePath":"classics/yixiaotie/128.md","filePath":"classics/yixiaotie/128.md"}'),o={name:"classics/yixiaotie/128.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷五·6",tabindex:"-1"},[r("卷五·6 "),e("a",{class:"header-anchor",href:"#卷五·6","aria-label":"Permalink to “卷五·6”"},"​")],-1),e("p",null,"遠宗讀易有太極，是生兩儀，兩儀生四象，四象生八卦諸語，不能釋然於心。如陳氏之徒，授受圖說，其非經悖聖，不必言矣。今傳本以一畫為太極，加一陰畫為兩儀，陰陽各二之為四象，極其精闢。然再四紬繹，猶似與陳氏相傳之說不甚相遠，何則？彼第以虛中夾畫為太極，一陰一陽為兩儀，不分二層，亦即以陰陽各二之為四象，而有老少之名，與我所為一畫而不虛中，陰陽各二之而不名老少，豈甚遠乎。夫庖犧以一畫始，即當畫至三畫乾也。三畫偶之即坤也。乾坤成而一索再索三索，即可成六子之卦，安見當日一必生二，二必生四，四而後生八也。以此轉展未安，不能無疑，乃反覆熟玩系傳前後文，竊意夫子太極兩儀四象之說，當耑為揲蓍言也。自大衍之數五十至易有聖人之道四焉者，此也復重提「天一地二天三地四天五地六天七地八天九地十」而申之，曰：夫易何為者也？夫易開物成務，冒天下之道，如斯而已者也。夫子於大衍之數如此其三致意也。而朱子不解其意，竟移天一諸語於大衍之數之前，真妄甚矣。大衍之數，蓍數也。揲蓍在八卦既畫之後，非八卦未畫之前也。是故易得而有之。蓋大衍之數，總而聚之，陰陽奇偶，渾然未判，謂之太極。太者大也，極者中也，喜怒哀樂之未發謂之中。中也者天下之大本也。陰陽奇偶之未判而謂之太極，亦猶是也。及分而為二以象兩，是生兩儀也。揲之以四以象四時，是生四象也。乃再扐而後掛，以至十有八變而成卦，是生八卦也。雖掛一象三，三字未嘗再及，然玩下文易有四象，所以示也。即繼之以系詞告，吉凶定，亦不言太極，亦不言兩儀，此不必泥也。且使四象在八卦未畫之前，則四象惟伏羲畫卦時有之，何以雲？所以示而繫辭以告，吉凶以定也。繫辭以告，吉凶以定，則在占筮之時也。則四象者，即是揲之以四以象四時，無疑也。而太極之為大衍未分，兩儀之為分之以二以象兩無疑也。且夫生之雲者，生生之謂易也。生變化，生吉凶，生情偽，生利害，參贊於神明而生蓍（生蓍非謂生蓍澤中，亦即因占筮而生）。發揮於剛柔而生爻皆是也，故一則曰易有，再則曰易有言，皆易之所有。而揲蓍時則生之者也。非推原作易之始也。乃若作易之始，夫子言之矣。「河出圖，洛出書，聖人則之」，是圖書者，聖人之所則，以作八卦者也。又曰：庖犧氏之王天下也，仰以觀於天文，俯以察於地理，觀鳥獸之文與地之宜，近取諸身，遠取諸物，於是始作八卦，即聖人則之之說也。此則言作易之始也。曰作卦所以別乎生卦也。故曰：太極兩儀四象之說，當耑為卜筮言也。卜筮之道，聖人成能，百姓與能，故言聖人洗心藏密。聖人齋戒以神明其德，推而至於利用出入，民鹹用之之謂神。直接是故易有太極云云。又推言法象變化之大，而總以為莫大於蓍龜，又推言聖人法天地圖書，以為作卦之本。而結之曰：易有四象，所以示也。繫辭焉，所以告也。定之以吉凶，所以斷也。夫子之意本是深切著明，而後人何用紛紛其說乎。觀崔憬以捨一蓍為太極，又或以四十九數合而未分時為太極，則古人相承，原有耑指卜筮言者。而其後言人人殊，遂失之矣。然本文前後脈絡貫串，自無他指。只順文解經便可瞭然。故敢附呈管見稟問可否，冒昧死罪。",-1)])])}const x=t(o,[["render",c]]);export{f as __pageData,x as default};
